function bindPage(route,parts){$('print')?.addEventListener('click',()=>window.print());view.querySelectorAll('[data-scroll]').forEach(a=>a.onclick=x=>{x.preventDefault();rememberSection(parts[1],a.dataset.scroll);$('section-'+a.dataset.scroll).scrollIntoView({behavior:'smooth',block:'start'});});view.querySelectorAll('[data-letter]').forEach(a=>a.onclick=x=>{x.preventDefault();$('letter-'+a.dataset.letter).scrollIntoView({behavior:'smooth'});});if($('local-query')){$('local-query').oninput=x=>{searchState.q=x.target.value;filtered();};$('search-scope').onchange=x=>{searchState.scope=x.target.value;filtered();};$('clear-search').onclick=()=>{searchState={q:'',domain:'',depth:'',scope:''};$('query').value='';location.hash='bok';render(false);};$('domain').onchange=x=>{searchState.domain=x.target.value;filtered();};$('depth').onchange=x=>{searchState.depth=x.target.value;filtered();};filtered();}if($('note')){$('note').oninput=x=>{try{localStorage.setItem('bcl-note-'+parts[1],x.target.value);$('note-status').textContent=tr('saved');}catch{$('note-status').textContent=tr('saveError');}};$('export-note').onclick=()=>download(parts[1]+'-analisis.txt',$('note').value,'text/plain;charset=utf-8');}if(parts[0]==='cuaderno')bindWork(+parts[1],+(parts[2]||0));if(parts[0]==='dossier')$('download-dossier').onclick=()=>download('fontys-luk-'+parts[1]+'-dossier.html','<!doctype html><html lang="'+lang+'"><meta charset="utf-8"><title>'+e(tr('work'))+'</title><style>body{max-width:900px;margin:30px auto;padding:20px;font:17px/1.6 Arial}table{border-collapse:collapse;width:100%}td,th{border:1px solid #663366;padding:10px;vertical-align:top}h2{color:#663366}td{overflow-wrap:anywhere}</style><body>'+$('dossier-body').innerHTML+'</body></html>','text/html;charset=utf-8');}
const STUDY_KEY='bcl-study-tools-v1';let study={version:1,items:[],lists:[],sourceNotes:{},corpusNotes:{},last:null,topicWork:{}},studyWritable=true;
const sourceFields=['sourceConsultation','sourcePassage','sourceClaim','sourceQuestion','sourceData','sourceFinding','sourceLimits','sourceConnection','sourceDecision'];const corpusFields=['hypothesis','resourceVersion','searchScope','queryRecord','sampleSelection','sampleProvenance','sampleStatus','observations','counterexamples','comparisonLimits','conclusion'];
function validateStudy(d){if(d?.version!==1||!Array.isArray(d.items)||d.items.length>2000||!Array.isArray(d.lists)||d.lists.length>100||!d.sourceNotes||!d.corpusNotes)throw Error(tr('invalidCopy'));if(d.lists.some(l=>typeof l!=='string'||l.length>100))throw Error(tr('invalidCopy'));for(const x of d.items)if(!['topic','source','example'].includes(x.kind)||typeof x.id!=='string'||x.id.length>120||typeof x.list!=='string'||x.list.length>100||(x.kind==='example'&&(!Number.isInteger(x.index)||x.index<0)))throw Error(tr('invalidCopy'));for(const notes of [d.sourceNotes,d.corpusNotes,d.topicWork||{}]){if(typeof notes!=='object'||Array.isArray(notes))throw Error(tr('invalidCopy'));for(const v of Object.values(notes)){if(!v||typeof v!=='object'||Array.isArray(v)||Object.values(v).some(s=>typeof s!=='string'||s.length>20000))throw Error(tr('invalidCopy'));}}if(d.last&&(typeof d.last.slug!=='string'||typeof d.last.section!=='string'))throw Error(tr('invalidCopy'));return {...structuredClone(d),topicWork:structuredClone(d.topicWork||{})};}
try{const raw=localStorage.getItem(STUDY_KEY);if(raw)study=validateStudy(JSON.parse(raw));}catch{studyWritable=false;}
function saveStudy(){if(window.BCL_PREVIEW_CONTENT)return false;if(!studyWritable)return false;try{localStorage.setItem(STUDY_KEY,JSON.stringify(study));return true;}catch{return false;}}
