function popularLinks(){return '<div class="suggested"><h2>'+e(tr('popular'))+'</h2><div class="concepts">'+(C.popularTopics||[]).filter(p=>topic(p.topic)).map(p=>'<a href="#buscar/'+encodeURIComponent(val(p.query))+'">'+e(val(p.label))+'</a>').join('')+'</div><p class="meta">'+e(tr('popularHelp'))+'</p><details><summary>'+e(tr('pluralismHelp').split('.')[0])+'</summary><p>'+e(tr('pluralismHelp'))+'</p></details></div>';}
