function resumeLink(){const t=topic(study.last?.slug);return t?'<a class="button secondary" href="#tema/'+e(t.slug)+'?section='+e(study.last.section||'overview')+'">'+e(tr('continueReading'))+': '+e(val(t.title))+'</a>':'';}
function refreshSuggestions(){const dl=$('search-suggestions');if(!dl)return;const options=new Set();for(const p of C.popularTopics||[])options.add(val(p.query));for(const t of allTopics()){options.add(val(t.title));for(const w of t.terms)options.add(w);}for(const a of C.searchAliases||[])for(const w of val(a.terms).split('\n'))if(w)options.add(w);dl.innerHTML=[...options].map(w=>'<option value="'+e(w)+'"></option>').join('');}
function topicAliases(t){return (C.searchAliases||[]).filter(a=>a.topic===t.slug).flatMap(a=>Object.values(a.terms).flatMap(s=>s.split('\n')));}
function selectedSearchText(t){if(searchState.scope==='titles')return JSON.stringify([t.title,t.summary,topicAliases(t)]);if(searchState.scope==='terms')return JSON.stringify([t.terms,topicAliases(t)]);if(searchState.scope==='examples')return JSON.stringify([t.examples,t.case,t.authentic?.text,t.contrastSamples,t.study?.caseData,t.study?.reasoning?.newCase,samplesFor(t.slug)]);if(searchState.scope==='sources')return t.references.map(id=>source(id)?.apa||'').join(' ');return JSON.stringify(t)+' '+JSON.stringify(samplesFor(t.slug))+' '+topicAliases(t).join(' ')+' '+t.references.map(id=>source(id)?.apa||'').join(' ');}
function snippet(t){if(!searchState.q)return '';const q=norm(searchState.q);const parts=[val(t.summary),val(t.theory),val(t.case),...t.examples,...samplesFor(t.slug).flatMap(x=>[x.text,val(x.title),val(x.analysis)]),...t.references.map(id=>source(id)?.apa||'')];const part=parts.find(s=>norm(s).includes(q))||val(t.summary);const pos=norm(part).indexOf(q);const start=Math.max(0,pos-55);const fragment=(start?'… ':'')+part.slice(start,start+180)+(part.length>start+180?' …':'');return '<p class="search-fragment"><strong>'+e(tr('matchedFragment'))+':</strong> '+e(fragment)+'</p>';}
function ris(r){const clean=s=>String(s||'').replace(/[\r\n]+/g,' ').trim();const meta=r.citation||{};let lines=['TY  - '+(['JOUR','BOOK','ELEC','GEN'].includes(meta.type)?meta.type:'GEN'),'TI  - '+clean(r.title)];for(const a of (meta.authors||'').split('\n').filter(Boolean))lines.push('AU  - '+clean(a));if(/^\d{4}$/.test(meta.year))lines.push('PY  - '+meta.year);for(const [key,tag]of [['journal','JO'],['volume','VL'],['issue','IS'],['publisher','PB']])if(meta[key])lines.push(tag+'  - '+clean(meta[key]));if(meta.pages){const range=String(meta.pages).match(/^(\d+)[–-](\d+)$/);if(range)lines.push('SP  - '+range[1],'EP  - '+range[2]);else lines.push('SP  - '+clean(meta.pages));}lines.push('UR  - '+safeUrl(r.url),'N1  - '+clean(r.apa));const doi=r.url.match(/^https:\/\/doi\.org\/(.+)$/);if(doi)lines.push('DO  - '+doi[1]);lines.push('ER  - ');return lines.join('\r\n')+'\r\n';}
